from collections import deque

def accessible(g,conn=4):
 n,m=g.shape
 seen=np.zeros(g.shape,bool)
 q=deque([(0,0)]); seen[0,0]=True
 dirs=([(1,0),(-1,0),(0,1),(0,-1)] if conn==4 else [(dr,dc) for dr in(-1,0,1) for dc in(-1,0,1) if dr or dc])
 while q:
  r,c=q.popleft()
  for dr,dc in dirs:
   rr,cc=r+dr,c+dc
   if 0<=rr<n and 0<=cc<m and not seen[rr,cc] and g[rr,cc]!=1:
    seen[rr,cc]=True;q.append((rr,cc))
 return seen

def pred_boundary(g, adj=4, seedconn=4, boundary=True):
 n,m=g.shape; region=accessible(g,seedconn); out=g.copy()
 dirs=([(1,0),(-1,0),(0,1),(0,-1)] if adj==4 else [(dr,dc) for dr in(-1,0,1) for dc in(-1,0,1) if dr or dc])
 for r in range(n):
  for c in range(m):
   if g[r,c]!=8 or not region[r,c]: continue
   touch=boundary and (r==0 or c==0 or r==n-1 or c==m-1)
   if not touch:
    touch=any(0<=r+dr<n and 0<=c+dc<m and g[r+dr,c+dc]==1 for dr,dc in dirs)
   if touch: out[r,c]=7
 return out
