def comps(g,conn=4):
 n,m=g.shape; seen=np.zeros(g.shape,bool); dirs=([(1,0),(-1,0),(0,1),(0,-1)] if conn==4 else [(dr,dc) for dr in(-1,0,1) for dc in(-1,0,1) if dr or dc]); out=[]
 for r in range(n):
  for c in range(m):
   if g[r,c]!=1 or seen[r,c]: continue
   q=[(r,c)]; seen[r,c]=1; comp=[]
   for x,y in q:
    comp.append((x,y))
    for dr,dc in dirs:
     rr,cc=x+dr,y+dc
     if 0<=rr<n and 0<=cc<m and g[rr,cc]==1 and not seen[rr,cc]:
      seen[rr,cc]=1;q.append((rr,cc))
   out.append(comp)
 return out

def pred_bordercomps(g, adj=8, seedconn=4, compconn=4, boundary=True, require_reach=True):
 n,m=g.shape; region=accessible(g,seedconn); out=g.copy()
 dirs=([(1,0),(-1,0),(0,1),(0,-1)] if adj==4 else [(dr,dc) for dr in(-1,0,1) for dc in(-1,0,1) if dr or dc])
 selected=set()
 for comp in comps(g,compconn):
  if any(r in(0,n-1) or c in(0,m-1) for r,c in comp): selected.update(comp)
 for r in range(n):
  for c in range(m):
   if g[r,c]!=8 or (require_reach and not region[r,c]): continue
   touch=boundary and (r==0 or c==0 or r==n-1 or c==m-1)
   if not touch:
    touch=any((r+dr,c+dc) in selected for dr,dc in dirs)
   if touch: out[r,c]=7
 return out
